<?php authorizeAdmin($u); ?><p class="page-intro">Registro de las últimas 300 actuaciones. Las decisiones del trámite se conservan con su fecha, hora y responsable.</p><section class="panel"><div class="table-wrap"><table><thead><tr><th>Fecha y hora</th><th>Responsable</th><th>Acción</th><th>Detalle</th><th>Solicitud</th></tr></thead><tbody><?php foreach(rows('SELECT e.*,u.name FROM events e JOIN users u ON u.id=e.actor_id ORDER BY e.id DESC LIMIT 300') as $ev): ?><tr><td><?=e($ev['created_at'])?></td><td><?=e($ev['name'])?></td><td><?=e($ev['action'])?></td><td><?=e($ev['detail'])?></td><td><?php if($ev['request_id']): ?><a href="/?page=request&id=<?=(int)$ev['request_id']?>">TH-<?=(int)$ev['request_id']?></a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
